import{_ as a,o as t,c as n,a6 as o}from"./chunks/framework.BrkgobfX.js";const h=JSON.parse('{"title":"条件请求","description":"ETag 强弱比较、Last-Modified 验证器与五个 If-* 字段的求值优先级。","frontmatter":{"title":"条件请求","description":"ETag 强弱比较、Last-Modified 验证器与五个 If-* 字段的求值优先级。","source":"https://daiw.org/manual/http11/conditional-requests"},"headers":[],"relativePath":"manual/computer-programming/http11/conditional-requests.md","filePath":"manual/computer-programming/http11/conditional-requests.md"}'),s={name:"manual/computer-programming/http11/conditional-requests.md"};function d(i,e,c,r,l,p){return t(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="条件请求" tabindex="-1">条件请求 <a class="header-anchor" href="#条件请求" aria-label="Permalink to &quot;条件请求&quot;">​</a></h1><h2 id="etag" tabindex="-1">ETag <a class="header-anchor" href="#etag" aria-label="Permalink to &quot;ETag&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ETag       = entity-tag</span></span>
<span class="line"><span>entity-tag = [ weak ] opaque-tag</span></span>
<span class="line"><span>weak       = %s&quot;W/&quot;</span></span>
<span class="line"><span>opaque-tag = DQUOTE *etagc DQUOTE</span></span>
<span class="line"><span>etagc      = %x21 / %x23-7E / obs-text</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ETag: &quot;33a64df551425fcc55e4d42a148795d9f25f89d4&quot;</span></span>
<span class="line"><span>ETag: W/&quot;v1.2&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>逐条约束：</p><ul><li><strong>双引号是语法的一部分</strong>，不可省略。<code>ETag: abc</code> 非法——这是最常见的实现错误。</li><li>前缀 <code>W/</code> <strong>大小写敏感</strong>（<code>%s</code> 表示区分大小写），且必须紧贴引号。</li><li>标签内容对客户端<strong>完全不透明</strong>：不得解析、不得比较大小、不得推断含义。</li><li>内容不可含 <code>&quot;</code>（0x22）本身。</li><li>生成方式不限（哈希、版本号、时间戳皆可），但<strong>必须</strong>在表示改变时改变。</li></ul><h3 id="强验证器-vs-弱验证器" tabindex="-1">强验证器 vs 弱验证器 <a class="header-anchor" href="#强验证器-vs-弱验证器" aria-label="Permalink to &quot;强验证器 vs 弱验证器&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>强（<code>&quot;x&quot;</code>）</th><th>弱（<code>W/&quot;x&quot;</code>）</th></tr></thead><tbody><tr><td>保证</td><td><strong>字节级完全相同</strong></td><td>语义等价即可，字节可不同</td></tr><tr><td>可用于 <code>Range</code></td><td>✅</td><td>❌</td></tr><tr><td>典型来源</td><td>内容哈希</td><td>「内容没实质变化」的人工判断</td></tr></tbody></table><p><strong>gzip 压缩会改变字节</strong>——同一资源的压缩版与非压缩版<strong>必须</strong>用不同的强 ETag，否则范围请求会拼出损坏的文件。许多服务器在启用动态压缩时错误地保留原 ETag 或简单地加后缀，这是真实存在的数据损坏源。</p><h3 id="两种比较算法" tabindex="-1">两种比较算法 <a class="header-anchor" href="#两种比较算法" aria-label="Permalink to &quot;两种比较算法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>算法</th><th>规则</th><th>用于</th></tr></thead><tbody><tr><td><strong>强比较</strong></td><td>两者均为<strong>强</strong>验证器 且 字节相同</td><td><code>If-Match</code>、<code>If-Range</code></td></tr><tr><td><strong>弱比较</strong></td><td>字节相同即可，<strong>忽略</strong> <code>W/</code> 前缀</td><td><code>If-None-Match</code></td></tr></tbody></table><p>例：<code>W/&quot;1&quot;</code> 与 <code>W/&quot;1&quot;</code> 弱比较<strong>匹配</strong>、强比较<strong>不匹配</strong>；<code>&quot;1&quot;</code> 与 <code>W/&quot;1&quot;</code> 两种比较都<strong>不匹配</strong>（前缀不同即字节不同）。</p><h2 id="last-modified" tabindex="-1">Last-Modified <a class="header-anchor" href="#last-modified" aria-label="Permalink to &quot;Last-Modified&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Last-Modified = HTTP-date</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>表示的最后修改时刻，是<strong>弱验证器</strong>（精度仅到秒，同一秒内的多次修改无法区分）。</p><ul><li><strong>MUST NOT</strong> 晚于响应的 <code>Date</code>。</li><li>仅当满足以下之一时才可当作<strong>强</strong>验证器：修改时间与 <code>Date</code> 相差至少 1 秒，或缓存有其他手段确认该秒内无变更。</li><li>服务端应<strong>同时</strong>发 <code>ETag</code> 与 <code>Last-Modified</code>——前者精确，后者兼容旧客户端与启发式缓存计算。</li></ul><h2 id="五个条件字段" tabindex="-1">五个条件字段 <a class="header-anchor" href="#五个条件字段" aria-label="Permalink to &quot;五个条件字段&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>If-Match            = &quot;*&quot; / #entity-tag</span></span>
<span class="line"><span>If-None-Match       = &quot;*&quot; / #entity-tag</span></span>
<span class="line"><span>If-Modified-Since   = HTTP-date</span></span>
<span class="line"><span>If-Unmodified-Since = HTTP-date</span></span>
<span class="line"><span>If-Range            = entity-tag / HTTP-date</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="if-match" tabindex="-1">If-Match <a class="header-anchor" href="#if-match" aria-label="Permalink to &quot;If-Match&quot;">​</a></h3><p><strong>强比较</strong>。用于<strong>避免丢失更新</strong>（乐观并发控制）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PUT /doc HTTP/1.1</span></span>
<span class="line"><span>If-Match: &quot;v1&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><ul><li>匹配 → 正常执行。</li><li>不匹配 → <strong>412 Precondition Failed</strong>，请求不得产生副作用。</li><li><code>*</code> → 只要资源<strong>当前存在</strong>就通过。</li></ul><h3 id="if-none-match" tabindex="-1">If-None-Match <a class="header-anchor" href="#if-none-match" aria-label="Permalink to &quot;If-None-Match&quot;">​</a></h3><p><strong>弱比较</strong>。两种用途：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /doc HTTP/1.1</span></span>
<span class="line"><span>If-None-Match: &quot;v1&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><ul><li><strong>缓存验证</strong>（<code>GET</code>/<code>HEAD</code>）：匹配 → <strong>304 Not Modified</strong>；不匹配 → 正常 <code>200</code>。</li><li><strong>避免覆盖</strong>（其他方法）：<code>If-None-Match: *</code> 表示「仅当资源<strong>不存在</strong>时才执行」——用于原子创建，已存在则返回 <code>412</code>。</li></ul><h3 id="if-modified-since" tabindex="-1">If-Modified-Since <a class="header-anchor" href="#if-modified-since" aria-label="Permalink to &quot;If-Modified-Since&quot;">​</a></h3><p>仅对 <code>GET</code>/<code>HEAD</code> 有效，且<strong>仅在无 <code>If-None-Match</code> 时</strong>才求值。</p><ul><li>资源在该时刻后<strong>未</strong>修改 → <code>304</code>。</li><li>已修改 → <code>200</code>。</li><li>日期无效或晚于服务端当前时间 → <strong>MUST 忽略</strong>该字段。</li></ul><h3 id="if-unmodified-since" tabindex="-1">If-Unmodified-Since <a class="header-anchor" href="#if-unmodified-since" aria-label="Permalink to &quot;If-Unmodified-Since&quot;">​</a></h3><p><code>If-Match</code> 的日期版，仅在<strong>无 <code>If-Match</code></strong> 时求值。未修改 → 执行；已修改 → <code>412</code>。</p><h3 id="if-range" tabindex="-1">If-Range <a class="header-anchor" href="#if-range" aria-label="Permalink to &quot;If-Range&quot;">​</a></h3><p>见<a href="/Front2Full/manual/computer-programming/http11/range-requests">范围请求</a>。仅在有 <code>Range</code> 时求值，<strong>强比较</strong>。</p><h2 id="求值优先级-must-按序" tabindex="-1">求值优先级（MUST 按序） <a class="header-anchor" href="#求值优先级-must-按序" aria-label="Permalink to &quot;求值优先级（MUST 按序）&quot;">​</a></h2><p>多个条件字段同时出现时，接收方 <strong>MUST</strong> 按此顺序求值，<strong>先命中先返回</strong>：</p><ol><li><strong><code>If-Match</code></strong> 存在 → 求值。假 → <code>412</code>。</li><li><code>If-Match</code> <strong>不存在</strong> 且 <code>If-Unmodified-Since</code> 存在 → 求值。假 → <code>412</code>。</li><li><strong><code>If-None-Match</code></strong> 存在 → 求值。假（即匹配上了）→ <code>GET</code>/<code>HEAD</code> 返回 <code>304</code>，其他方法返回 <code>412</code>。</li><li>方法为 <code>GET</code>/<code>HEAD</code> 且 <code>If-None-Match</code> <strong>不存在</strong> 且 <code>If-Modified-Since</code> 存在 → 求值。假 → <code>304</code>。</li><li>方法为 <code>GET</code> 且有 <code>Range</code> 且 <code>If-Range</code> 存在 → 求值。真 → <code>206</code>；假 → 忽略 <code>Range</code>，返回完整 <code>200</code>。</li></ol><p>关键推论：<strong>ETag 优先于日期</strong>。同时发 <code>If-None-Match</code> 与 <code>If-Modified-Since</code> 时，后者被完全忽略——这是有意设计，因为 ETag 更精确。</p><h2 id="_304-响应的构造" tabindex="-1">304 响应的构造 <a class="header-anchor" href="#_304-响应的构造" aria-label="Permalink to &quot;304 响应的构造&quot;">​</a></h2><p>命中缓存验证时：</p><ul><li><strong>MUST NOT</strong> 有消息体。</li><li><strong>MUST</strong> 带若返回 <code>200</code> 时会发的 <code>ETag</code>、<code>Last-Modified</code>（若有）。</li><li><strong>SHOULD</strong> 带 <code>Cache-Control</code>、<code>Vary</code>、<code>Expires</code>、<code>Date</code>、<code>Content-Location</code>。</li><li><strong>不应</strong>带 <code>Content-Type</code>、<code>Content-Encoding</code> 等描述体的字段（无体可描述）。</li><li>缓存收到后 <strong>MUST</strong> 用这些头更新已存储副本，再把更新后的完整响应交给客户端。</li></ul><h2 id="副作用约束" tabindex="-1">副作用约束 <a class="header-anchor" href="#副作用约束" aria-label="Permalink to &quot;副作用约束&quot;">​</a></h2><p>条件求值为<strong>假</strong>时，请求 <strong>MUST NOT</strong> 产生任何副作用。这是 <code>If-Match</code> 能实现并发控制的前提：服务端必须在<strong>执行前</strong>求值，且求值与执行需相对于其他并发请求保持原子。</p><p>下一篇：<a href="/Front2Full/manual/computer-programming/http11/range-requests">范围请求</a>——Range、Content-Range 与 206 的构造。</p>`,43)])])}const u=a(s,[["render",d]]);export{h as __pageData,u as default};
